from typing import List

class Solution:
    def maximumBooks(self, books: List[int]) -> int:
        n = len(books)
        dp = [0] * n
        max_books = 0

        for i in range(n):
            if books[i] == 0:
                dp[i] = 0
            else:
                if i == 0:
                    dp[i] = books[i]
                else:
                    prev = dp[i - 1]
                    if books[i] > books[i - 1]:
                        dp[i] = books[i] + dp[i - 1]
                    else:
                        dp[i] = books[i] + min(dp[i - 1] - books[i - 1] + 1, 0)
                max_books = max(max_books, dp[i])

        return max_books
```

