class Solution:
    def distributeCandies(self, n: int, limit: int) -> int:
        import math

        def count_ways(total):
            if total < 0:
                return 0
            # Number of non-negative integer solutions to x1 + x2 + x3 = total
            # with 0 <= xi <= limit
            if total < 0 or total > 3 * limit:
                return 0
            return (total + 2) * (total + 1) // 2  # stars and bars: C(total + 3 - 1, 3 - 1)

        def f(total):
            # Number of non-negative solutions to x1 + x2 + x3 = total
            return count_ways(total)

        # Total ways without any constraint
        total = f(n)

        def subtract_one(limit):
            # Subtract cases where one child gets more than limit
            return f(n - (limit + 1))

        def subtract_two(limit):
            # Subtract cases where two children get more than limit
            return f(n - 2 * (limit + 1))

        def subtract_three(limit):
            # Subtract cases where all three children get more than limit
            return f(n - 3 * (limit + 1))

        # Inclusion-Exclusion
        res = total
        res -= 3 * subtract_one(limit)
        res += 3 * subtract_two(limit)
        res -= subtract_three(limit)

        return max(res, 0)

    def run_tests(self):
        # Example 1
        print(self.distributeCandies(5, 2))  # Output: 3
        # Example 2
        print(self.distributeCandies(3, 3))  # Output: 10
```

