                else:  # b == f
                    min_row = min(a, e)
                    max_row = max(a, e)
                    for row in range(min_row + 1, max_row):
                        if (row, b) == (c, d):
                            return False
                return True
            return False

        def is_bishop_under_attack(c, d, e, f):
