                dx = 1 if c < e else -1
                dy = 1 if d < f else -1
                x, y = c + dx, d + dy
                while x != e or y != f:
                    if (x, y) == (a, b):
                        return False
                    x += dx
                    y += dy
                return True
            return False

        if can_bishop_capture_in_two_moves(c, d, e, f, a, b):
