class Solution:
    def smallestValue(self, n: int) -> int:
        def sum_of_prime_factors(x):
            if x == 1:
                return 0
            total = 0
            i = 2
            while i * i <= x:
                while x % i == 0:
                    total += i
                    x //= i
                i += 1
            if x > 1:
                total += x
            return total

        while True:
            # If n is already the smallest, return it
            if n < 2:
                return n
            # Compute the sum of prime factors
            s = sum_of_prime_factors(n)
            if s < n:
                n = s
