from typing import List

class Solution:
    def maximumInvitations(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Build adjacency list
        graph = [[] for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    graph[i].append(j)

        # Match for each girl
        match_to = [-1] * n

        def bpm(u, visited):
            for v in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    if match_to[v] == -1 or bpm(match_to[v], visited):
                        match_to[v] = u
                        return True
            return False

        result = 0
        for u in range(m):
            visited = [False] * n
            if bpm(u, visited):
                result += 1

        return result
