class Solution:
    def minWindow(self, s1: str, s2: str) -> str:
        if not s1 or not s2:
            return ""

        m, n = len(s1), len(s2)
        # Preprocess: for each position in s1 and each char, store the next index
        next_pos = [[-1] * 26 for _ in range(m)]

        # Fill next_pos
        for i in range(m - 1, -1, -1):
            for c in range(26):
                if ord(s1[i]) == ord('a') + c:
                    next_pos[i][c] = i
                else:
                    next_pos[i][c] = next_pos[i + 1][c] if i + 1 < m else -1

        # dp[i][j]: the length of the shortest substring starting at i in s1 that contains s2[:j] as a subsequence
        dp = [[float('inf')] * (n + 1) for _ in range(m)]

        for i in range(m):
            dp[i][0] = 0  # base case: empty subsequence

        # Fill dp
        for i in range(m):
            for j in range(1, n + 1):
                if s1[i] == s2[j - 1]:
                    dp[i][j] = 1 + dp[i + 1][j - 1] if i + 1 < m else 1
                else:
                    if i + 1 < m:
                        dp[i][j] = min(dp[i + 1][j], dp[i][j])
                    else:
                        dp[i][j] = dp[i][j]

        min_len = float('inf')
        result = ""

        # Find the minimum length substring
        for i in range(m):
            for j in range(n + 1):
                if dp[i][j] < min_len:
                    min_len = dp[i][j]
                    result = s1[i:i + dp[i][j]]

        return result

