class Solution:
    def minCostII(self, costs: List[List[int]]) -> int:
        if not costs:
            return 0

        n = len(costs)
        k = len(costs[0])

        if k == 1:
            return sum(costs[i][0] for i in range(n))

        # Initialize DP table with the same dimensions as costs
        dp = [[0] * k for _ in range(n)]

