    def encode(self, s: str) -> str:
        from functools import lru_cache

        def encode_helper(s, start, end):
            if start == end:
                return s
            if start == 0:
                s = s
            else:
                s = s[start:end+1]
            if start == 0:
                cache = {}
                for i in range(1, end - start + 1):
                    if s[:i] * (end - start - i + 1) == s[start:end+1]:
                        current = f"{end - start - i + 1}[{encode_helper(s, start, start + i - 1)}]"
                        if len(current) < len(s):
                            return current
                return s
            res = s
            for i in range(start + 1, end + 1):
                left = encode_helper(s, start, i - 1)
                right = encode_helper(s, i, end)
                if left and right:
                    combined = left + right
                    if len(combined) < len(res):
                        res = combined
            return res

        memo = {}
        def dp(s, i, j):
            if (i, j) in memo:
                return memo[(i, j)]
            if i == j:
                memo[(i, j)] = s[i:j+1]
                return s[i:j+1]
            res = s[i:j+1]
            for k in range(i, j):
                left = dp(s, i, k)
                right = dp(s, k+1, j)
                if len(left) + len(right) < len(res):
                    res = left + right
            for k in range(i, j):
                l = j - k
                if l == 0:
                    continue
                if (s[i:j+1] == s[i:i+l] * (l + 1) // l):
                    encoded = f"{(l + 1) // l}[{dp(s, i, i + l - 1)}]"
                    if len(encoded) < len(res):
                        res = encoded
            memo[(i, j)] = res
            return res

        return dp(s, 0, len(s)-1)

