from typing import List

class Solution:
    def movesToChessboard(self, board: List[List[int]]) -> int:
        n = len(board)
        if n == 1:
            return 0

        def is_valid_board(board):
            for i in range(n):
                for j in range(n):
                    if (board[i][j] + board[i][j ^ 1]) % 2 != 1:
                        return False
            return True

        def count_mismatches(board, target):
            count = 0
            for i in range(n):
                for j in range(n):
                    if board[i][j] != target[i][j]:
                        count += 1
            return count

        def get_pattern(board, is_row):
            pattern = []
            for i in range(n):
                if is_row:
                    pattern.append(board[i][0])
                else:
                    pattern.append(board[0][i])
            return pattern

        # Check if the board is a valid chessboard
        if not is_valid_board(board):
            return -1

        # Check for row and column pattern
        row1 = [0] * n
        row2 = [1] * n
        col1 = [0] * n
        col2 = [1] * n

        # Find the number of rows that match row1 and row2
        row1_count = 0
        row2_count = 0
        for i in range(n):
            if board[i] == row1:
                row1_count += 1
            elif board[i] == row2:
                row2_count += 1
            else:
                return -1

        if (n % 2 == 1):
            if row1_count != row2_count:
                return -1
        else:
            if abs(row1_count - row2_count) > 1:
                return -1

        # Similarly for columns
        col1_count = 0
        col2_count = 0
        for i in range(n):
            if board[0][i] == 0:
                col1_count += 1
            elif board[0][i] == 1:
                col2_count += 1
            else:
                return -1

        if n % 2 == 1:
            if col1_count != col2_count:
                return -1
        else:
            if abs(col1_count - col2_count) > 1:
                return -1

        def count_moves(board, is_row):
            if is_row:
                target = row1
                if (n % 2 == 1):
                    if board[0][0] == 1:
                        target = row2
                pattern = target
            else:
                target = col1
                if (n % 2 == 1):
                    if board[0][0] == 1:
                        target = col2
                pattern = target

            moves = 0
            for i in range(n):
                if board[i] != pattern:
                    if (i % 2 == 0 and board[i] != pattern):
                        moves += 1
                    elif (i % 2 == 1 and board[i] != pattern):
                        moves += 1
            return moves

        row_moves = count_moves(board, True)
        col_moves = count_moves(board, False)

        return row_moves + col_moves

