class Solution:
    def minOperationsToFlip(self, expression: str) -> int:
        def evaluate(s: str) -> (int, int):
            stack = []
            i = 0
            while i < len(s):
                if s[i] == '(':
                    stack.append(('(', i))
                    i += 1
                elif s[i] == ')':
                    # Pop from stack until '('
                    j = i
                    while j > stack[-1][1]:
                        j -= 1
                    if s[j] == '(':
                        # Handle the inner expression
                        inner, inner_cost = evaluate(s[stack[-1][1]+1:j])
                        stack.pop()
                        if stack:
                            op = stack[-1][0]
                            left_val, left_cost = stack.pop()
                            if op == '&':
