from typing import List

class Solution:
    def splitIntoFibonacci(self, num: str) -> List[int]:
        n = len(num)
        result = []

        def backtrack(start, path):
            if len(path) >= 3 and start == n:
                return path
            for i in range(start + 1, n + 1):
                if i - start > 10:
                    continue  # To avoid very long numbers
                s = num[start:i]
                if s[0] == '0' and len(s) > 1:
                    continue  # Skip leading zeros
                num_val = int(s)
                if num_val >= 2**31:
                    continue  # Check 32-bit integer limit
                if not path:
                    path.append(num_val)
                elif len(path) == 1:
                    path.append(num_val)
                elif len(path) == 2:
                    if path[0] + path[1] == num_val:
                        path.append(num_val)
                else:
                    # For more than 2 elements, we need to check if the last two sum to current
                    if path[-1] + path[-2] == num_val:
                        path.append(num_val)
                res = backtrack(i, path)
                if res:
                    return res
                path.pop()
            return []

        return backtrack(0, [])

