    sol = Solution()
    print(sol.racecar(3))  # Output: 2
    print(sol.racecar(6))  # Output: 5
    print(sol.racecar(1))  # Output: 1
    print(sol.racecar(2))  # Output: 3
    print(sol.racecar(4))  # Output: 4

if __name__ == "__main__":
    run_tests()
```

