                return not is_blocked(a, b, e, f, c, d)
            if is_same_col(a, b, e, f):
                return not is_blocked(a, b, e, f, c, d)
            return False

        def bishop_can_capture():
            if is_same_diag(c, d, e, f):
                return not is_blocked(c, d, e, f, a, b)
            return False

        if rook_can_capture() or bishop_can_capture():
            return 1

        def rook_min_moves():
            if is_same_row(a, b, e, f):
                if (a, f) == (e, f):
                    return 1
                # Move to same row (e, f)
                return 1
            if is_same_col(a, b, e, f):
                if (f, b) == (e, f):
                    return 1
                return 1
            # Rook must move to same row or column, then move to queen
            return 2

        def bishop_min_moves():
            if is_same_diag(c, d, e, f):
                if (c, d) == (e, f):
                    return 1
                return 1
            return 2

        return min(rook_min_moves(), bishop_min_moves())

