from typing import List

class Solution:
    def findAndReplacePattern(self, words: List[str], pattern: str) -> List[str]:
        def get_pattern(s: str) -> List[int]:
            mapping = {}
            mapped = []
            for char in s:
                if char not in mapping:
                    mapping[char] = len(mapping)
                mapped.append(mapping[char])
            return mapped

        pattern_map = get_pattern(pattern)
        result = []

        for word in words:
            if get_pattern(word) == pattern_map:
                result.append(word)

        return result
