import sys
sys.setrecursionlimit(1000000)
MOD = 10**9 + 7

class Solution:
    def goodBinaryStrings(self, minLength: int, maxLength: int, oneGroup: int, zeroGroup: int) -> int:
        from functools import lru_cache

        def is_valid_string(s):
            i = 0
            while i < len(s):
                if s[i] == '1':
                    j = i
                    while j < len(s) and s[j] == '1':
                        j += 1
                    if (j - i) % oneGroup != 0:
                        return False
                    i = j
                else:
                    j = i
                    while j < len(s) and s[j] == '0':
                        j += 1
                    if (j - i) % zeroGroup != 0:
                        return False
                    i = j
            return True

        def count_valid_strings(n):
            if n < minLength or n > maxLength:
                return 0
            if n == 0:
                return 1 if 0 % oneGroup == 0 and 0 % zeroGroup == 0 else 0

            result = 0

            # Try adding a 0
            if n >= 1:
                if (1 % zeroGroup == 0):
                    result += count_valid_strings(n - 1)

            # Try adding a 1
            if n >= 1:
                if (1 % oneGroup == 0):
                    result += count_valid_strings(n - 1)

            return result % MOD

        return count_valid_strings(maxLength)

