To solve this problem efficiently, we use **digit dynamic programming (digit DP)** to count the number of integers between 1 and a number (like `num2`) whose digit sum is within the given range `[min_sum, max_sum]`. We then subtract the count from 1 to `num1 - 1` to get the final count in the range `[num1, num2]`.

We will:

1. Define a helper function `count_less_or_equal(s, min_sum, max_sum)` that counts how many numbers from 0 to `s` have digit sums between `min_sum` and `max_sum`.
2. Use digit DP to compute that count.
3. Compute the result as `count_less_or_equal(num2, min_sum, max_sum) - count_less_or_equal(num1, min_sum, max_sum)`.

We also need to handle the case where `num1` is "0", but since the problem says `1 <= num1`, we can assume `num1` is always at least 1.

Here's the full code:

```python
import sys
sys.setrecursionlimit(10000)

MOD = 10**9 + 7

class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        def digit_sum(x):
            s = 0
            while x > 0:
                s += x % 10
                x //= 10
            return s

        def count_less_or_equal(s: str, m_min: int, m_max: int) -> int:
            from functools import lru_cache

            n = len(s)
            digits = list(map(int, s))

            @lru_cache(None)
            def dp(pos, tight, sum_so_far, leading_zero):
                if pos == n:
                    return 1 if m_min <= sum_so_far <= m_max else 0

                limit = digits[pos] if tight else 9
                res = 0

                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_leading_zero = leading_zero and (d == 0)
                    if not new_leading_zero:
                        new_sum = sum_so_far + d
                    else:
                        new_sum = sum_so_far

                    if not new_leading_zero:
                        res += dp(pos + 1, new_tight, new_sum, new_leading_zero)
                    else:
                        res += dp(pos + 1, new_tight, 0, new_leading_zero)

                    res %= MOD

                return res

            return dp(0, True, 0, True)

        def solve(s):
            return count_less_or_equal(s, min_sum, max_sum)

        res = solve(num2) - solve(num1)
        return res % MOD

    def run_tests(self):
        print(self.count("1", "12", 1, 8))  # Expected output: 11
        print(self.count("1", "5", 1, 5))   # Expected output: 5
```

