class Solution:
    def soupServings(self, n: int) -> float:
        import functools

        def convert(n):
            return (n + 24) // 25  # round up to the next 25 unit boundary

        if n == 0:
            return 1.0

        k = convert(n)
        memo = {}

        def dp(a, b):
            if (a, b) in memo:
                return memo[(a, b)]

            if a <= 0 and b <= 0:
                return 0.5  # both empty
            if a <= 0:
                return 1.0  # A is empty first
            if b <= 0:
                return 0.0  # B is empty first

            res = 0.25 * (dp(a - 1, b) + dp(a - 1, b - 1) + dp(a - 2, b - 2) + dp(a - 3, b - 3))
            memo[(a, b)] = res
            return res

        return dp(k, k)
```

