### Strategy:

- Use **digit dynamic programming (digit DP)** to compute the number of integers from `0` to `num` whose digit sum is between `min_sum` and `max_sum`.
- Then compute the number of valid integers between `num1` and `num2` as `f(num2) - f(num1 - 1)`.

We will define a helper function `count_less_equal(num, min_sum, max_sum)` that computes the number of numbers up to `num` that have a digit sum between `min_sum` and `max_sum`.

We'll use memoization and recursion to implement digit DP.

Here is the full implementation:

```python
class Solution:
    MOD = 10**9 + 7

    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        from functools import lru_cache

        def count_less_equal(s, target_min, target_max):
            n = len(s)
            @lru_cache(None)
            def dp(pos, tight, sum_so_far, leading_zero):
                if pos == n:
                    return 1 if (target_min <= sum_so_far <= target_max) else 0

                limit = int(s[pos]) if tight else 9
                res = 0

                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_sum = sum_so_far + d
                    if leading_zero and d == 0:
                        new_leading_zero = True
                    else:
                        new_leading_zero = False
                    if not new_leading_zero:
                        new_sum = sum_so_far + d
                    else:
                        new_sum = sum_so_far
                    res += dp(pos + 1, new_tight, new_sum, new_leading_zero)
                    res %= self.MOD

                return res

            return dp(0, True, 0, True)

        def subtract_one(s):
            if s == '0':
                return '0'
            s = list(s)
            i = len(s) - 1
            while i >= 0 and s[i] == '0':
                s[i] = '9'
                i -= 1
            if i < 0:
                return '0' * (len(s) + 1)
            s[i] = str(int(s[i]) - 1)
            return ''.join(s)

        def compute(s):
            if s == '0':
                return 0
            return count_less_equal(s, min_sum, max_sum)

        def helper(s):
            res = count_less_equal(s, min_sum, max_sum)
            return res

        def count_between(a, b):
            if a == "0":
                return helper(b)
            return (helper(b) - helper(subtract_one(a))) % self.MOD

        return count_between(num1, num2)

    def run_tests(self):
        # Test case 1
        self.assertEqual(self.count("1", "12", 1, 8), 11)
        # Test case 2
        self.assertEqual(self.count("1", "5", 1, 5), 5)
```

