import sys
sys.setrecursionlimit(10000)
from functools import lru_cache

class Solution:
    MOD = 10**9 + 7

    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        def subtract_one(s):
            s = list(s)
            i = len(s) - 1
            while i >= 0 and s[i] == '0':
                s[i] = '9'
                i -= 1
            if i < 0:
                return '0'  # This shouldn't happen for valid input
            s[i] = str(int(s[i]) - 1)
            if s[0] == '0' and len(s) > 1:
                s = s[1:]
            return ''.join(s)

        def digit_sum(x):
            return sum(int(d) for d in x)

        def count_less_or_equal(s, min_sum, max_sum):
            n = len(s)
            @lru_cache(maxsize=None)
            def dp(pos, tight, sum_so_far, leading_zero):
                if pos == n:
                    return 1 if min_sum <= sum_so_far <= max_sum else 0
                limit = int(s[pos]) if tight else 9
                total = 0
                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_sum = sum_so_far + d
                    new_leading_zero = leading_zero and (d == 0)
                    if not new_leading_zero:
                        total += dp(pos + 1, new_tight, new_sum, new_leading_zero)
                    else:
                        total += dp(pos + 1, new_tight, new_sum, new_leading_zero)
                return total % self.MOD

            return dp(0, True, 0, True)

        def solve(s):
            return count_less_or_equal(s, min_sum, max_sum)

        upper = solve(num2)
        lower = solve(subtract_one(num1))
        return (upper - lower) % self.MOD

