from typing import List

class Solution:
    def pourWater(self, heights: List[int], volume: int, k: int) -> List[int]:
        def pour_one_drop():
            # Try to move left
            i = k
            while i > 0:
                if heights[i] > heights[i - 1]:
                    break
                elif heights[i] == heights[i - 1]:
                    i -= 1
                else:
                    # It can fall, move left
                    i -= 1
                    break
            if i > 0:
                # Check if it can eventually fall further left
                # If we moved to i, we need to find the lowest possible position to the left
                pos = i
                while pos > 0:
                    if heights[pos] > heights[pos - 1]:
                        break
                    elif heights[pos] < heights[pos - 1]:
                        # We can fall further
                        pos -= 1
                    else:
                        # We can move further
                        pos -= 1
                # Update the position to the lowest possible left
                if pos > 0:
                    heights[pos] += 1
                    return
                else:
                    # Can't move left, try right
                    i = k
                    while i < len(heights) - 1:
                        if heights[i] > heights[i + 1]:
                            break
                        elif heights[i] == heights[i + 1]:
                            i += 1
                        else:
                            i += 1
                            break
                    if i < len(heights) - 1:
                        # Can fall right, move right
                        heights[i] += 1
                        return
                    else:
                        # No direction to fall, stay at k
                        heights[k] += 1
                        return
            else:
                # Can't move left, try right
                i = k
                while i < len(heights) - 1:
                    if heights[i] > heights[i + 1]:
                        break
                    elif heights[i] == heights[i + 1]:
                        i += 1
                    else:
                        i += 1
                        break
                if i < len(heights) - 1:
                    heights[i] += 1
                    return
                else:
                    heights[k] += 1

        # Make a copy of heights to avoid modifying the original
        current_heights = list(heights)
        for _ in range(volume):
            pour_one_drop()
        return current_heights
```

