            if num == "":
                return False
            if num[0] == '0' and len(num) > 1:
                return False
            if '.' in num:
                parts = num.split('.')
                if len(parts) != 2:
                    return False
                if parts[0] == '' or parts[1] == '':
                    return False
                if parts[0] == '0' and len(parts[0]) > 1:
