                if parts[0] != '0' and parts[1] != '0':
                    return True
                return False
            else:
                if num == '0':
                    return True
                if num[0] == '0':
                    return False
                return True

        def generate(num_str: str) -> List[str]:
            res = []
            for i in range(1, len(num_str)):
                if i == 1:
                    num1 = num_str[:i]
                    num2 = num_str[i:]
                    if valid(num1) and valid(num2):
                        res.append(f"({num1}, {num2})")
                else:
                    if valid(num_str[:i]) and valid(num_str[i:]):
                        res.append(f"({num_str[:i]}, {num_str[i:]})")
            return res

        for i in range(1, len(s) - 1):
            if i == 1:
                first = s[:i]
                second = s[i:]
                for a in generate(first):
                    for b in generate(second):
                        res.append(a + b)
            else:
                for a in generate(s[:i]):
                    for b in generate(s[i:]):
                        res.append(a + b)

        return res
