                        moves += 1
                else:
                    if board[i][0] != (1 - start):
                        moves += 1
            return moves

        # Check for both possible configurations (starting with 0 or 1)
        # For rows
        row0 = board[0]
        row1 = [1 - x for x in row0]
        moves_rows_start0 = 0
        moves_rows_start1 = 0

        for i in range(n):
