```python
import sys
import functools

MOD = 10**9 + 7

class Solution:
    def goodBinaryStrings(self, minLength: int, maxLength: int, oneGroup: int, zeroGroup: int) -> int:
        from functools import lru_cache

        @lru_cache(None)
        def dfs(pos, last_type, last_len):
            if pos > maxLength:
                return 0
            if pos >= minLength:
                res = 0
                if last_type == 0:
                    res = dfs(pos + 1, 0, 0)
                    res += dfs(pos + 1, 1, 0)
                elif last_type == 1:
                    res = dfs(pos + 1, 1, 0)
                    res += dfs(pos + 1, 0, 0)
                else:
                    res = dfs(pos + 1, 1, 0)
                    res += dfs(pos + 1, 0, 0)
                return res
            else:
                res = 0
                if last_type == 0:
                    res += dfs(pos + last_len, 0, last_len)
                elif last_type == 1:
                    res += dfs(pos + last_len, 1, last_len)
                else:
                    # Start with a 1 block
                    if last_len == 0:
                        for k in range(1, oneGroup + 1):
                            if k > maxLength - pos:
                                continue
                            res += dfs(pos + k, 1, k)
                    # Start with a 0 block
                    if last_len == 0:
                        for k in range(1, zeroGroup + 1):
                            if k > maxLength - pos:
                                continue
                            res += dfs(pos + k, 0, k)
                return res % MOD

        return dfs(0, 0, 0) % MOD
```

### Explanation:

- The `dfs` function is a recursive function with memoization that explores all possible binary strings.
- The function tracks the current position in the string and the type of the last block (0 or 1) and the length of that block.
- For each position, it tries to continue the current block if it's valid (i.e., the block size is a multiple of the corresponding group).
- It also tries to start a new block of the opposite type.

