from typing import List, Dict, Set, Tuple, Any
from collections import defaultdict, deque

class Solution:
    def deleteDuplicateFolder(self, paths: List[List[str]]) -> List[List[str]]:
        def build_tree(paths: List[List[str]]) -> Dict[str, Dict[str, Any]]:
            root = {}
            for path in paths:
                current = root
                for name in path[:-1]:
                    if name not in current:
                        current[name] = {}
                    current = current[name]
                current[path[-1]] = True
            return root

        def get_hash(node: Dict, visited: Set[Tuple[int, int]] = None) -> str:
            if visited is None:
                visited = set()
            key = str(id(node))
            if key in visited:
                return key
            visited.add(key)
            hash_str = str(id(node))
            for name, child in node.items():
                hash_str += f"{name}:{get_hash(child, visited)}"
            return hash_str

        def find_duplicates(root: Dict, hash_map: Dict[str, List[Tuple[int, int]]]) -> Dict[str, List[Tuple[int, int]]]:
            def traverse(node: Dict, parent: Tuple[int, int] = (0, 0), depth: int = 0):
                key = str(id(node))
                hash_str = str(id(node))
                for name, child in node.items():
                    hash_str += f"{name}:{traverse(child, (id(node), id(child)), depth + 1)}"
                if hash_str not in hash_map:
                    hash_map[hash_str] = []
                hash_map[hash_str].append((id(node), id(child)))
                return node

            hash_map = {}
            traverse(root)
            return hash_map

        def mark_nodes(root: Dict, to_remove: Set[Tuple[int, int]]):
            def traverse(node: Dict, parent: Tuple[int, int] = (0, 0)):
                for name, child in node.items():
                    if (id(node), id(child)) in to_remove:
                        del node[name]
                    else:
                        traverse(child, (id(node), id(child)))
            traverse(root)

        def build_paths(root: Dict, current_path: List[str], result: List[List[str]]) -> List[List[str]]:
            def traverse(node: Dict, path: List[str]):
                for name, child in node.items():
                    path.append(name)
                    result.append(list(path))
                    traverse(child, path)
                    path.pop()
            traverse(root, [])
            return result

        # Build the trie
        trie = build_tree(paths)

        # Find duplicate subtrees
        hash_map = {}
        find_duplicates(trie, hash_map)

        # Find all duplicate hashes with more than one occurrence
        duplicate_hashes = [hash_str for hash_str, lst in hash_map.items() if len(lst) > 1]

        # Collect the nodes to be removed
        to_remove = set()
        for hash_str in duplicate_hashes:
            for (id_node, id_child) in hash_map[hash_str]:
                to_remove.add((id_node, id_child))

        # Mark all nodes that are in to_remove
        mark_nodes(trie, to_remove)

        # Build the final result
        result = build_paths(trie, [], [])

        return result
