class Solution:
    def maxConsecutiveAnswers(self, answerKey: str, k: int) -> int:
        def max_consecutive_same_char(s, k, target):
            left = 0
            max_len = 0
            count = 0
            for right in range(len(s)):
                if s[right] != target:
                    count += 1
                while count > k:
                    if s[left] != target:
                        count -= 1
                    left += 1
                max_len = max(max_len, right - left + 1)
            return max_len

        return max(max_consecutive_same_char(answerKey, k, 'T'), max_consecutive_same_char(answerKey, k, 'F'))

