                            stack.pop()  # remove '('
                        if res:
                            stack.append(evaluate(''.join(res)))
                else:
                    stack.append(c)
            return stack

        def parse(expr):
            if expr[0] in '01':
                return (int(expr[0]), 1 - int(expr[0]))
            elif expr[0] == '(':
                left, right = parse(expr[1:-1])
                return left, right
            else:
                left = parse(expr[:2])
                right = parse(expr[2:])
                if expr[1] == '&':
                    if left[0] and right[0]:
                        val = 1
                        cost = min(left[1], right[1])
                    elif left[0] and not right[0]:
                        val = 1
                        cost = left[1] + right[1]
                    elif not left[0] and right[0]:
                        val = 1
                        cost = left[1] + right[1]
                    elif not left[0] and not right[0]:
                        val = 0
                        cost = min(left[1], right[1])
                    return (val, cost)
                else:  # '|' operator
                    if left[0] or right[0]:
                        val = 1
                        cost = min(left[1], right[1])
                    elif left[0] and right[0]:
                        val = 1
                        cost = left[1] + right[1]
                    elif not left[0] and not right[0]:
                        val = 0
                        cost = min(left[1], right[1])
                    return (val, cost)
            return (1, 1)

        result, cost = parse(expression)
        return cost

    def run_tests(self):
        test_cases = [
            ("1&(0|1)", 1),
            ("(0&0)&(0&0&0)", 3),
            ("(0|(1|0&1))", 1),
        ]
        for expr, expected in test_cases:
            result = self.minOperationsToFlip(expr)
            assert result == expected, f"Failed on {expr}: expected {expected}, got {result}"
        print("All tests passed.")

# Test the solution
sol = Solution()
sol.run_tests()
