To solve this problem, we need to compute the number of integers between `num1` and `num2` (inclusive) whose digit sum lies within the range `[min_sum, max_sum]`.

We'll use **digit dynamic programming (digit DP)** to efficiently count such numbers. The idea is to compute the number of valid numbers from `0` to `num` and then compute the result as:

> `count(num2) - count(num1 - 1)`

But since `num1` and `num2` are strings, we need to convert them to integers (or process as strings for handling very large values).

We will use memoization to speed up the DP computation.

Here is the full implementation:

```python
import sys
from functools import lru_cache

MOD = 10**9 + 7

class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        def digit_sum(x):
            return sum(int(d) for d in x)

        def get_num(s):
            return int(s)

        def count_less_or_equal(s, max_sum):
            n = len(s)
            s = list(map(int, s))
            @lru_cache(maxsize=None)
            def dp(pos, tight, sum_so_far, leading_zero):
                if pos == n:
                    if sum_so_far >= min_sum and sum_so_far <= max_sum:
                        return 1
                    return 0
                res = 0
                upper = s[pos] if tight else 9
                for d in range(0, upper + 1):
                    new_tight = tight and (d == upper)
                    new_leading_zero = leading_zero and (d == 0)
                    new_sum = sum_so_far + d
                    if not new_leading_zero:
                        res += dp(pos + 1, new_tight, new_sum, new_leading_zero)
                    else:
                        res += dp(pos + 1, new_tight, new_sum, new_leading_zero)
                    res %= MOD
                return res
            return dp(0, True, 0, True)

        def compute(s):
            n = len(s)
            s = list(map(int, s))
            @lru_cache(maxsize=None)
            def dp(pos, tight, sum_so_far, leading_zero):
                if pos == n:
                    if sum_so_far >= min_sum and sum_so_far <= max_sum:
                        return 1
                    return 0
                res = 0
                upper = s[pos] if tight else 9
                for d in range(0, upper + 1):
                    new_tight = tight and (d == upper)
                    new_leading_zero = leading_zero and (d == 0)
                    new_sum = sum_so_far + d
                    if not new_leading_zero:
                        res += dp(pos + 1, new_tight, new_sum, new_leading_zero)
                    else:
                        res += dp(pos + 1, new_tight, new_sum, new_leading_zero)
                    res %= MOD
                return res
            return dp(0, True, 0, True)

        def subtract(a, b):
            a = int(a)
            b = int(b)
            if a < b:
                return 0
            return compute(str(a)) - compute(str(b - 1))

        if num1 == "0":
            res = compute(num2)
        else:
            res = compute(num2) - compute(num1 - 1)
            res %= MOD
        return res % MOD

    def run_tests(self):
        # Example 1
        res1 = self.count("1", "12", 1, 8)
        print(f"Test 1: {res1}")

        # Example 2
        res2 = self.count("1", "5", 1, 5)
        print(f"Test 2: {res2}")
```

### Notes:
- `compute(s)` computes how many numbers less than or equal to `s` have digit sums in the `[min_sum, max_sum]` range.
- `subtract(a, b)` computes the number of valid numbers in the range `[b, a]` by calculating `compute(a) - compute(b - 1)`.
- The `digit_sum` function is not directly used in this implementation since we are using digit DP.

