To solve this problem efficiently, we can use **digit dynamic programming** (digit DP), which is suitable for counting numbers with certain digit constraints within a large range represented as strings.

### Key Concepts:
- A **stepping number** is a number where the absolute difference between all adjacent digits is exactly 1.
- We need to find the count of all such numbers in the range [low, high].
- Since the range can be extremely large (up to $10^{100}$), we cannot directly iterate over all numbers in the range.
- We'll use digit DP to count stepping numbers from 0 to a given number (as a string), and then use the inclusion-exclusion principle to compute the count for [low, high].

### Plan:
1. Implement a helper function `count_stepping_up_to(s)` that returns the count of stepping numbers from 0 to s (as a string).
2. Use inclusion-exclusion:
   - `count_stepping(high) - count_stepping(low - 1)`
   - Handle edge cases like leading zero.
3. For the digit DP, we'll:
   - Use memoization to avoid recomputing states.
   - Track:
     - Position in the number.
     - Tight constraint (whether the previous digits match the input number).
     - Previous digit.
     - Whether the number is valid so far.
     - Whether the number has started (to avoid leading zeros).

Here is the full implementation:

```python
import sys
from functools import lru_cache

MOD = 10**9 + 7

class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        def count_stepping(s: str) -> int:
            @lru_cache(maxsize=None)
            def dp(pos, tight, prev_digit, started, is_valid):
                if pos == len(s):
                    return 1 if is_valid else 0

                limit = int(s[pos]) if tight else 9
                res = 0

                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_started = started or d != 0
                    new_is_valid = is_valid
                    if not started:
                        new_is_valid = True
                    else:
                        if abs(d - prev_digit) != 1:
                            new_is_valid = False
                        else:
                            new_is_valid = is_valid

                    if not new_started:
                        res += dp(pos + 1, new_tight, d, new_started, new_is_valid)
                    else:
                        res += dp(pos + 1, new_tight, d, new_started, new_is_valid)

                return res % MOD

            return dp(0, True, -1, False, False)

        def convert_to_int(s):
            if s == "0":
                return 0
            return int(s)

        def subtract_one(s):
            s_list = list(s)
            i = len(s_list) - 1
            while i >= 0 and s_list[i] == '0':
                s_list[i] = '9'
                i -= 1
            if i < 0:
                return "0"
            s_list[i] = str(int(s_list[i]) - 1)
            if s_list[0] == '0':
                s_list = s_list[1:]
            return ''.join(s_list)

        def count_stepping_with_leading_zero(s: str) -> int:
            if len(s) == 0:
                return 0
            if s[0] == '0':
                return count_stepping(s[1:])
            else:
                return count_stepping(s)

        def count_stepping_range(s: str) -> int:
            if s == "0":
                return 1
            return count_stepping_with_leading_zero(s)

        if low == "0":
            return count_stepping_range(high)
        elif high == "0":
            return 0
        else:
            # We need to count numbers from low to high
            def count_between(a, b):
                return (count_stepping_range(b) - count_stepping_range(a - 1)) % MOD

            try:
                high_int = int(high)
                low_int = int(low)
                if low_int <= high_int:
                    return count_between(low, high)
                else:
                    return 0
            except:
                return 0

        return 0

    def run_tests(self):
        test_cases = [
            ("1", "11", 10),
            ("90", "101", 2),
            ("1", "1", 1),
            ("0", "0", 1),
            ("0", "1", 2),
            ("10", "10", 1),
            ("10", "20", 2),
        ]

        for low, high, expected in test_cases:
            result = self.countSteppingNumbers(low, high)
            print(f"Test case: low={low}, high={high}, expected={expected}, got={result}")
            assert result == expected, f"Failed for {low}, {high}"
        print("All test cases passed.")

# To run tests, call run_tests() from the Solution class
sol = Solution()
sol.run_tests()
```

