We can implement this with a function `count_digits(n, d)` that computes the number of times digit `d` appears in all numbers from 1 to `n`. This is based on a well-known algorithm for counting digit appearances.

Here's the full implementation of the `digitsCount` method:

```python
class Solution:
    def digitsCount(self, d: int, low: int, high: int) -> int:
        def count(n: int, d: int) -> int:
            if d == 0 and n == 0:
                return 1
            if n < 0:
                return 0
            res = 0
            i = 1
            while i <= n:
                divider = i * 10
                higher = n // divider
                current = (n // i) % 10
                lower = n % i

                if d == 0:
                    higher -= 1
                    if higher < 0:
                        higher = 0
                if d == 0 and higher == 0:
                    res += lower + 1
                else:
                    res += (higher + 1) * i
                    if d == current:
                        res += lower + 1
                    elif d == 0:
                        res += i
                i *= 10
            return res

        def count_digits(n, d):
            if d == 0:
                return count(n, d)
            else:
                return count(n, d) - count(10**(len(str(n)) - 1) - 1, d)

        if d == 0:
            return count_digits(high, d) - count_digits(low - 1, d)
        else:
            return count(high, d) - count(low - 1, d)

    def run_tests(self):
        # Example test cases
        test1 = self.digitsCount(1, 1, 13)
        test2 = self.digitsCount(3, 100, 250)
        print(f"Test 1: Expected 6, Got {test1}")
        print(f"Test 2: Expected 35, Got {test2}")
```

