To solve this problem, we need to efficiently count the number of integers between two large numeric strings `num1` and `num2` such that the digit sum of each is between `min_sum` and `max_sum`.

Since `num1` and `num2` can be as large as `10^22`, we cannot directly iterate through all numbers. Instead, we can use **digit dynamic programming** (digit DP) to count the number of valid numbers up to a given number.

The approach is as follows:

1. Define a helper function `count_less_or_equal(s)` that returns the number of integers from `0` to `s` (inclusive) whose digit sum is within the range `[min_sum, max_sum]`.

2. The total number of good integers is `count_less_or_equal(num2) - count_less_or_equal(num1 - 1)`.

3. We use memoization and recursion with memoization to perform digit DP.

Here is the full implementation:

```python
class Solution:
    MOD = 10**9 + 7
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        from functools import lru_cache

        def digit_sum(x):
            return sum(int(c) for c in x)

        def count_less_or_equal(s):
            n = len(s)
            @lru_cache(None)
            def dp(pos, tight, sum_so_far, leading_zero):
                if pos == n:
                    return 1 if min_sum <= sum_so_far <= max_sum else 0

                limit = int(s[pos]) if tight else 9
                res = 0
                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_sum = sum_so_far + d
                    if leading_zero and d == 0:
                        res += dp(pos + 1, new_tight, new_sum, True)
                    else:
                        res += dp(pos + 1, new_tight, new_sum, False)
                return res

            return dp(0, True, 0, True)

        def subtract_one(s):
            s = list(s)
            i = len(s) - 1
            while i >= 0 and s[i] == '0':
                s[i] = '9'
                i -= 1
            if i < 0:
                return None
            s[i] = str(int(s[i]) - 1)
            if s[0] == '0':
                s = s[1:]
            return ''.join(s)

        def compute(num):
            n = len(num)
            @lru_cache(None)
            def dp(pos, tight, sum_so_far, leading_zero):
                if pos == n:
                    return 1 if min_sum <= sum_so_far <= max_sum else 0
                limit = int(num[pos]) if tight else 9
                res = 0
                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_sum = sum_so_far + d
                    if leading_zero and d == 0:
                        res += dp(pos + 1, new_tight, new_sum, True)
                    else:
                        res += dp(pos + 1, new_tight, new_sum, False)
                return res

            return dp(0, True, 0, True)

        total = compute(num2)
        if num1 == "0":
            return total
        else:
            num1_minus_1 = subtract_one(num1)
            if num1_minus_1 is None:
                return total
            else:
                return (total - compute(num1_minus_1)) % self.MOD

