import math

class Solution:
    def judgePoint24(self, cards: List[int]) -> bool:
        def dfs(nums):
            if len(nums) == 1:
                return abs(nums[0] - 24) < 1e-6
            for i in range(len(nums)):
                for j in range(len(nums)):
                    if i != j:
                        a, b = nums[i], nums[j]
                        new_nums = [nums[k] for k in range(len(nums)) if k != i and k != j]
                        for op in ['+', '-', '*', '/']:
                            if op == '+':
                                new_nums.append(a + b)
                            elif op == '-':
                                new_nums.append(a - b)
                            elif op == '*':
                                new_nums.append(a * b)
                            elif op == '/':
                                if b == 0:
                                    continue
                                new_nums.append(a / b)
                            if dfs(new_nums):
                                return True
                        new_nums.clear()
            return False

        return dfs(cards)
