MOD = 10**9 + 7

class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        from functools import lru_cache

        def digit_sum(x):
            return sum(int(d) for d in x)

        def count_less_or_equal(num_str, min_s, max_s):
            n = len(num_str)
            num = [int(d) for d in num_str]

            @lru_cache(None)
            def dp(pos, tight, s, leading_zero):
                if pos == n:
                    if min_s <= s <= max_s:
                        return 1
                    else:
                        return 0
                limit = num[pos] if tight else 9
                total = 0
                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_s = s + d
                    if leading_zero and d == 0:
                        total += dp(pos + 1, new_tight, new_s, True)
                    else:
                        total += dp(pos + 1, new_tight, new_s, False)
                return total

            return dp(0, True, 0, True)

        def subtract(num1, num2):
            if int(num1) > int(num2):
                return 0
            return count_less_or_equal(num2, min_sum, max_sum) - count_less_or_equal(num1, min_sum, max_sum)

        # Compute count from 0 to num1 - 1
        def decrement(num):
            if num == "0":
                return "0"
            num_list = [int(d) for d in num]
            carry = 1
            for i in range(len(num_list) - 1, -1, -1):
                new_val = num_list[i] - carry
                if new_val < 0:
                    new_val += 10
                    carry = 1
                else:
                    carry = 0
                num_list[i] = new_val
                if carry == 0:
                    break
            if carry:
                return "1" + "0" * len(num_list)
            else:
                return "".join(str(d) for d in num_list)

        # Handle case where num1 is "0"
        if num1 == "0":
            res = count_less_or_equal(num2, min_sum, max_sum)
        else:
            num1_minus_1 = decrement(num1)
            res = count_less_or_equal(num2, min_sum, max_sum) - count_less_or_equal(num1_minus_1, min_sum, max_sum)

        return res % MOD

    def run_tests(self):
        # Example 1
        self.count("1", "12", 1, 8)
        # Example 2
        self.count("1", "5", 1, 5)
```

