from typing import List

class Solution:
    def earliestAndLatest(self, n: int, firstPlayer: int, secondPlayer: int) -> List[int]:
        def get_rounds(players: List[int]) -> List[int]:
            rounds = []
            current_players = players.copy()
            current_round = 1

            while len(current_players) > 1:
                next_players = []
                m = len(current_players)
                for i in range(m):
                    if i == m // 2:
                        next_players.append(current_players[i])
                    elif i < m // 2:
                        next_players.append(current_players[i])
                    else:
                        next_players.append(current_players[m - i - 1])
                rounds.append(current_round)
                current_players = next_players
                current_round += 1
            return rounds

        def simulate_earliest(current_players: List[int], first: int, second: int) -> int:
            current_round = 1
            while True:
                idx1 = current_players.index(first)
                idx2 = current_players.index(second)
                if idx1 == idx2:
                    return current_round
                m = len(current_players)
                if idx1 == m // 2 or idx2 == m // 2:
                    return current_round
                if idx1 < idx2:
                    idx1 = m - idx1 - 1
                else:
                    idx2 = m - idx2 - 1
                # To find earliest, we can try to make them meet in the same position
                if idx1 == idx2:
                    return current_round
                next_players = []
                for i in range(m):
                    if i < m // 2:
                        next_players.append(current_players[i])
                    elif i == m // 2:
                        next_players.append(current_players[i])
                    else:
                        next_players.append(current_players[m - i - 1])
                current_players = next_players
                current_round += 1

        def simulate_latest(current_players: List[int], first: int, second: int) -> int:
            current_round = 1
            while True:
                idx1 = current_players.index(first)
                idx2 = current_players.index(second)
                if idx1 == idx2:
                    return current_round
                m = len(current_players)
                if idx1 < idx2:
                    idx1 = m - idx1 - 1
                else:
                    idx2 = m - idx2 - 1
                if idx1 == idx2:
                    return current_round
                next_players = []
                for i in range(m):
                    if i < m // 2:
                        next_players.append(current_players[i])
                    elif i == m // 2:
                        next_players.append(current_players[i])
                    else:
                        next_players.append(current_players[m - i - 1])
                current_players = next_players
                current_round += 1

        # Initial players in order
        initial_players = list(range(1, n + 1))
        earliest = simulate_earliest(initial_players, firstPlayer, secondPlayer)
        latest = simulate_latest(initial_players, firstPlayer, secondPlayer)

        return [earliest, latest]
