```python
class Solution:
    def smallestBeautifulString(self, s: str, k: int) -> str:
        from string import ascii_lowercase

        n = len(s)
        result = list(s)
        alphabet = list(ascii_lowercase[:k])

        def is_beautiful(string):
            for i in range(len(string) - 1):
                if string[i] == string[i + 1]:
                    return False
            for i in range(len(string) - 2):
                if string[i] == string[i + 2]:
                    return False
            return True

        def next_string(s):
            for i in range(len(s) - 1, -1, -1):
                if s[i] < alphabet[-1]:
                    for c in alphabet:
                        if c != s[i] and (i == 0 or c != s[i - 1]):
                            new_s = s[:i] + c + s[i + 1:]
                            if is_beautiful(new_s):
                                return new_s
                    return None
            return None

        def try_next_string():
            for i in range(n - 1, -1, -1):
                for c in alphabet:
                    if c != result[i] and (i == 0 or c != result[i - 1]):
                        new_s = result[:i] + c + result[i + 1:]
                        if is_beautiful(new_s):
                            if new_s > s:
                                return ''.join(new_s)
                            # Try to find the lex smallest one
                            for j in range(i + 1, n):
                                for c2 in alphabet:
                                    if c2 != new_s[j] and (j == i + 1 or c2 != new_s[j - 1]):
                                        new_s2 = new_s[:j] + c2 + new_s[j + 1:]
                                        if is_beautiful(new_s2):
                                            if new_s2 > s:
                                                return ''.join(new_s2)
            return ""

        # Try to increment the string from the end
        for i in range(n - 1, -1, -1):
            for c in alphabet:
                if c > s[i]:
                    new_s = list(s)
                    new_s[i] = c
                    if i > 0:
                        if new_s[i - 1] == c:
                            continue
                    if i + 1 < n:
                        if new_s[i + 1] == c:
                            continue
                    new_s = ''.join(new_s)
                    if is_beautiful(new_s) and new_s > s:
                        for j in range(i + 1, n):
                            for c2 in alphabet:
                                if c2 != new_s[j] and (j == i + 1 or c2 != new_s[j - 1]):
                                    temp = new_s[:j] + c2 + new_s[j + 1:]
                                    if is_beautiful(temp):
                                        if temp > s:
                                            return temp
                        return new_s
        return ""

    def run_tests(self):
        test_cases = [
            ("abcz", 26),
            ("dc", 4)
        ]
        for s, k in test_cases:
            res = self.smallestBeautifulString(s, k)
            print(f"Input: {s}, k={k} → Output: {res}")
```

