                if c == prev1 or c == prev2:
                    continue
                if i < n - 1:
                    s[i] = chr(ord('a') + c)
                else:
                    s[i] = chr(ord('a') + c)
                    return True
            return False

        def backtrack(i, prev1, prev2):
            if i == n:
                return ''.join(s)
            for c in range(0, k):
                if c == prev1 or c == prev2:
                    continue
                if i < n - 1:
                    s[i] = chr(ord('a') + c)
                else:
                    s[i] = chr(ord('a') + c)
                    return backtrack(i + 1, c, prev1)
                if is_beautiful(s):
                    res = backtrack(i + 1, c, prev1)
                    if res:
                        return res
                s[i] = chr(ord('a') + c)

            return ""

        # Try to increment s lexicographically
        for i in range(n - 1, -1, -1):
            for c in range(ord(s[i]) + 1, ord('a') + k):
                new_char = chr(c)
                if i < n - 1:
                    if new_char != s[i + 1] and new_char != s[i - 1] if i > 0 else True:
                        s[i] = new_char
                        for j in range(i + 1, n):
                            for next_c in range(ord('a'), ord('a') + k):
                                if next_c == s[j] or next_c == s[j - 1]:
                                    continue
                                s[j] = chr(next_c)
                                if is_beautiful(s):
                                    return ''.join(s)
                        # After trying all
                        s[i] = chr(ord('a') + c)
                        break
                else:
                    if i > 0 and new_char == s[i - 1]:
                        continue
                    s[i] = new_char
                    if is_beautiful(s):
                        return ''.join(s)

        return ""

    def run_tests(self):
        # For testing purposes, the user would use the method in this way
        # Example:
        print(self.smallestBeautifulString("abcz", 26))
        print(self.smallestBeautifulString("dc", 4))
