```python
from typing import List
import re
from collections import defaultdict

class Solution:
    def basicCalculatorIV(self, expression: str, evalvars: List[str], evalints: List[int]) -> List[str]:
        # Map for variables and their values
        var_map = dict(zip(evalvars, evalints))

        # Parse expression into tokens
        tokens = self.parse_expression(expression)

        # Evaluate the expression
        result = self.evaluate(tokens, var_map)

        # Format the result into the required output
        return self.format_result(result)

    def parse_expression(self, expr: str) -> List[str]:
        tokens = []
        i = 0
        while i < len(expr):
            if expr[i] == ' ':
                i += 1
                continue
            elif expr[i] == '(':
                tokens.append('(')
                i += 1
            elif expr[i] == ')':
                tokens.append(')')
                i += 1
            elif expr[i] in '+-':
                tokens.append(expr[i])
                i += 1
            else:
                # Read the token
                j = i
                while j < len(expr) and (expr[j].isalnum() or expr[j] == '*'):
                    j += 1
                tokens.append(expr[i:j])
                i = j
        return tokens

    def evaluate(self, tokens: List[str], var_map: dict) -> dict:
        # Each term is a dictionary: {var: coefficient, ...}, or int
        # The result is a list of terms (dicts)
        result = []

        # Using a stack for operator precedence and parentheses
        stack = []
        i = 0

        while i < len(tokens):
            token = tokens[i]

            if token == '(':
                stack.append(0)  # Start of a new expression
                i += 1
            elif token == ')':
                i += 1
                # We pop until we find '('
                while stack and stack[-1] != '(':
                    temp = self.parse_term(stack.pop())
                    if stack and isinstance(stack[-1], int):
                        stack[-1] += temp
                    else:
                        stack.append(temp)
                if stack:
                    stack.pop()  # Remove '('
            elif token in '+-':
                # Push current expression to stack
                if stack and isinstance(stack[-1], dict):
                    if stack[-1] not in result:
                        result.append(stack[-1])
                    stack.pop()
                stack.append(token)
                i += 1
            else:
                # Token is a number or variable
                if token in var_map:
                    val = var_map[token]
                    result.append({token: val})
                else:
                    # Try to parse as number
                    if token.isdigit():
                        result.append({token: int(token)})
                    else:
                        result.append({token: 1})
                i += 1

        # Final processing
        while stack:
            if isinstance(stack[-1], dict):
                if stack[-1] not in result:
                    result.append(stack[-1])
                stack.pop()
            else:
                stack.pop()

        # Combine like terms
        return self.combine_terms(result)

    def parse_term(self, term: dict) -> dict:
        if isinstance(term, dict):
            return term
        return {term: 1}

    def combine_terms(self, terms: List[dict]) -> dict:
        combined = defaultdict(int)
        for term in terms:
            if isinstance(term, dict):
                for var, coeff in term.items():
                    combined[var] += coeff
        # Convert defaultdict to dict
        res = dict(combined)
        # If all coefficients are zero, return empty dict
        if all(v == 0 for v in res.values()):
            return {}
        return res

    def format_result(self, result: dict) -> List[str]:
        terms = []
        # For constants
        if result and all(isinstance(k, str) for k in result.keys()) and all(isinstance(v, int) for v in result.values()):
            if sum(result.values()) != 0:
                terms.append(f"{sum(result.values())}")
        else:
            for var, coeff in sorted(result.items(), key=lambda x: (-len(x[0]), x[0])):
                if coeff != 0:
                    if coeff == 1:
                        coeff = ""
                    elif coeff == -1:
                        coeff = "-"
                    terms.append(f"{coeff}*{var}")

        # Sort the terms in the required order
        terms = sorted(terms, key=lambda x: (-(len(x.split('*')[-1])), x))
        return terms

    def evaluate_expression(self, tokens: List[str], var_map: dict) -> dict:
        # This is a helper function that evaluates the expression recursively
        # For now, we use a simpler version to handle multiplication and addition
        return self.evaluate(tokens, var_map)
