from typing import List

class Solution:
    def splitIntoFibonacci(self, num: str) -> List[int]:
        n = len(num)
        result = []

        def backtrack(start, prev1, prev2, current):
            if start == n:
                if len(current) >= 3:
                    return current
                else:
                    return []

            for i in range(start + 1, min(n, start + 12)):  # max length of a number is 10 digits
                s = num[start:i]
                if s[0] == '0' and len(s) > 1:
                    continue  # skip leading zero
                num_val = int(s)
                if num_val > 2**31 - 1:
                    continue  # exceed 32-bit signed int
                if not current:
                    # first number
                    result = [num_val]
                    current.append(num_val)
                elif len(current) == 1:
                    # second number
                    if prev1 + num_val == current[0]:
                        current.append(num_val)
                    else:
                        continue
                else:
                    # third and more
                    if prev1 + prev2 == num_val:
                        current.append(num_val)
                    else:
                        continue
                res = backtrack(i, current[-1], prev1, current)
                if res:
                    return res
                current.pop()
            return []

        return backtrack(0, 0, 0, [])

