class Solution:
    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        if not image or not image[0]:
            return 0

        m, n = len(image), len(image[0])

        def find_min_row() -> int:
            left, right = 0, m - 1
            while left <= right:
                mid = (left + right) // 2
                if any(image[mid][j] == '1' for j in range(n)):
                    right = mid - 1
                else:
                    left = mid + 1
            return left

        def find_max_row() -> int:
            left, right = 0, m - 1
            while left <= right:
                mid = (left + right) // 2
                if any(image[mid][j] == '1' for j in range(n)):
                    left = mid + 1
                else:
                    right = mid - 1
            return right

        def find_min_col() -> int:
            left, right = 0, n - 1
            while left <= right:
                mid = (left + right) // 2
                if any(image[i][mid] == '1' for i in range(m)):
                    right = mid - 1
                else:
                    left = mid + 1
            return left

        def find_max_col() -> int:
            left, right = 0, n - 1
            while left <= right:
                mid = (left + right) // 2
                if any(image[i][mid] == '1' for i in range(m)):
                    left = mid + 1
                else:
                    right = mid - 1
            return right

        min_row = find_min_row()
        max_row = find_max_row()
        min_col = find_min_col()
        max_col = find_max_col()

        return (max_row - min_row + 1) * (max_col - min_col + 1)
```

This solution runs in **O(log m + log n)** time due to binary searches on rows and columns, which is **less than O(mn)**, as required.
